package org.botai.back.b2b;

import java.time.Instant;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.botai.back.common.*;
import org.botai.back.grading.SubmissionStore;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.core.StreamReadFeature;
import tools.jackson.databind.*;
import tools.jackson.databind.json.JsonMapper;

/** Append-only observation facts. No arbitrary AI metadata reaches a browser or database event. */
@Service
@RequiredArgsConstructor
public class LocalDemoEvents {
    private static final JsonMapper JSON=JsonMapper.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
    private final SubmissionStore store;private final TransactionTemplate tx;
    private static final Set<String> TYPES=Set.of("stage_started","stage_completed","stage_failed","call_started","call_completed","call_failed","validation_failed","validation_completed","retry","artifact_created","run_started","run_completed","run_failed","validation_issue","retry_scheduled","artifact_available","artifact_ready","model_started","model_completed","model_failed","completed","failed","cancelled");
    private static final Set<String> PHASES=Set.of("input","task_preparation","task_input","ocr","layout","analysis","grading","validation","completed","failed","preparation","diagrams");
    private static final Set<String> SAFE_CODES=Set.of("format_invalid","invalid_stage_response","invalid_ai_response","validation_failed","llm_timeout","llm_error","llm_bad_response","provider_empty_choices","provider_output_truncated","internal_error","grading_busy","service_unavailable","invalid_task_snapshot","unsupported_task","unsupported_contract","image_count","image_size","image_dimensions","image_decode_failed","upload_disconnected","upload_too_large","unreadable","other_task","multiple_tasks","unrelated","attack","artifact_unavailable","trace_limit_exceeded","live_provider_disabled","cancelled_or_internal_error");
    public record ObserverJob(UUID run,UUID submission,long fence) { }
    public void track(UUID run,UUID submission){store.db().update("INSERT INTO local_demo_observer_jobs(ai_run_id,submission_id,fencing_token) SELECT id,submission_id,fencing_token FROM grading_runs WHERE id=? AND submission_id=? ON CONFLICT(ai_run_id) DO NOTHING",run,submission);}
    public List<ObserverJob> claimObservers(){return tx.execute(t->{observerTimeouts();return store.db().query("WITH picked AS(SELECT ai_run_id FROM local_demo_observer_jobs WHERE completed_at IS NULL AND incomplete_reason IS NULL AND expires_at>clock_timestamp() AND attempts<500 AND next_poll_at<=clock_timestamp() ORDER BY next_poll_at LIMIT 4 FOR UPDATE SKIP LOCKED) UPDATE local_demo_observer_jobs j SET attempts=attempts+1,next_poll_at=clock_timestamp()+interval '5 seconds' FROM picked p WHERE j.ai_run_id=p.ai_run_id RETURNING j.ai_run_id,j.submission_id,j.fencing_token",(r,n)->new ObserverJob(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getLong(3)));});}
    public void due(UUID run){store.db().update("UPDATE local_demo_observer_jobs SET next_poll_at=clock_timestamp() WHERE ai_run_id=? AND completed_at IS NULL AND incomplete_reason IS NULL",run);}
    public void finishObserver(UUID run){store.db().update("UPDATE local_demo_observer_jobs SET completed_at=clock_timestamp() WHERE ai_run_id=? AND completed_at IS NULL AND incomplete_reason IS NULL",run);}
    public void revokeObserver(UUID run){store.db().update("UPDATE local_demo_observer_jobs SET incomplete_reason='scope_revoked' WHERE ai_run_id=? AND completed_at IS NULL",run);}
    public boolean observerTarget(ObserverJob job){return store.db().queryForObject("SELECT count(*) FROM grading_runs WHERE id=? AND submission_id=? AND fencing_token=?",Integer.class,job.run,job.submission,job.fence)==1;}
    public boolean observedTerminal(UUID run){return store.db().queryForObject("SELECT count(*) FROM local_demo_observer_events o JOIN submission_events e ON e.id=o.event_id WHERE o.ai_run_id=? AND e.metadata->>'type' IN('completed','failed','cancelled','run_completed','run_failed')",Integer.class,run)>0;}
    public Object observerStatus(UUID submission){var rows=store.db().queryForList("SELECT j.completed_at,j.incomplete_reason,j.expires_at,j.attempts,EXISTS(SELECT 1 FROM submission_events e LEFT JOIN local_demo_public_events p ON p.source_event_id=e.id WHERE e.submission_id=j.submission_id AND p.seq IS NULL) unpublished FROM local_demo_observer_jobs j WHERE j.submission_id=? ORDER BY j.created_at DESC LIMIT 1",submission);Map<String,Object> status=new LinkedHashMap<>();if(rows.isEmpty()){status.put("state","not_started");status.put("expiresAt",null);return status;}var row=rows.getFirst();java.time.Instant expires=((java.sql.Timestamp)row.get("expires_at")).toInstant();boolean incomplete=row.get("incomplete_reason")!=null||expires.isBefore(java.time.Instant.now())||((Number)row.get("attempts")).intValue()>=500;status.put("state",row.get("completed_at")!=null?(Boolean.TRUE.equals(row.get("unpublished"))?"pending":"finished"):incomplete?"incomplete":"pending");status.put("expiresAt",expires.toString());return status;}
    private void observerTimeouts(){store.db().execute("SET LOCAL statement_timeout='200ms'");store.db().execute("SET LOCAL lock_timeout='100ms'");}
    public long observerCursor(UUID run){return store.db().queryForObject("SELECT coalesce(max(ai_seq),0) FROM local_demo_observer_events WHERE ai_run_id=?",Long.class,run);}
    public boolean importPage(UUID run,UUID submission,String raw){return importPage(run,submission,raw,Long.MAX_VALUE);}
    public boolean importPage(UUID run,UUID submission,String raw,long deadlineNanos){
        var root=JSON.readTree(raw);fields(root,"items","next_after","has_more");require(root.get("items").isArray()&&root.get("items").size()<=100&&root.get("next_after").isIntegralNumber()&&root.get("next_after").canConvertToLong()&&root.get("next_after").asLong()>=0&&root.get("has_more").isBoolean());long cursor=observerCursor(run),last=cursor;
        List<JsonNode> accepted=new ArrayList<>();for(var e:root.get("items")){fields(e,"seq","run_id","type","phase","created_at","data");require(e.get("seq").isIntegralNumber()&&e.get("seq").canConvertToLong());long seq=e.get("seq").asLong();require(seq>last&&seq<=512&&e.get("run_id").asText().equals(run.toString())&&e.get("type").isString()&&e.get("phase").isString()&&e.get("data").isObject());Instant.parse(e.get("created_at").asText());last=seq;accepted.add(e);}require(root.get("next_after").asLong()==last&&(!root.get("has_more").asBoolean()||!accepted.isEmpty()));
        tx.executeWithoutResult(t->{observerTimeouts();require(System.nanoTime()<deadlineNanos);store.db().queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?::text,995011))",run.toString());require(store.db().queryForObject("SELECT count(*) FROM grading_runs WHERE id=? AND submission_id=?",Integer.class,run,submission)==1);require(store.db().queryForObject("SELECT count(*) FROM local_demo_observer_events WHERE ai_run_id=?",Integer.class,run)<=512);for(var e:accepted){require(deadlineNanos==Long.MAX_VALUE||deadlineNanos-System.nanoTime()>650_000_000L);long seq=e.get("seq").asLong();if(store.db().queryForObject("SELECT count(*) FROM local_demo_observer_events WHERE ai_run_id=? AND ai_seq=?",Integer.class,run,seq)>0)continue;Map<String,Object> data=safeData(e.get("data"));String type=e.get("type").asText(),phase=e.get("phase").asText();Map<String,Object> metadata=new LinkedHashMap<>();metadata.put("type",TYPES.contains(type)?type:"observation");metadata.put("phase",PHASES.contains(phase)?phase:"ai_running");metadata.put("observedAt",e.get("created_at").asText());metadata.put("data",data);Long event=store.db().queryForObject("INSERT INTO submission_events(submission_id,event_type,metadata) VALUES(?,'local_ai_event',?::jsonb) RETURNING id",Long.class,submission,store.json().write(metadata));store.db().update("INSERT INTO local_demo_observer_events(ai_run_id,ai_seq,event_id) VALUES(?,?,?)",run,seq,event);}});return root.get("has_more").asBoolean()&&!accepted.isEmpty();
    }
    public static Map<String,Object> safeData(JsonNode raw){Map<String,Object> safe=new LinkedHashMap<>();if(raw==null||!raw.isObject())return safe;for(String key:List.of("attempt","task_number","image_count")){var v=raw.get(key);if(v!=null&&v.isIntegralNumber()&&v.canConvertToInt()&&v.asInt()>=0&&v.asInt()<=10000)safe.put(camel(key),v.asInt());}var duration=raw.get("duration_ms");if(duration!=null&&duration.isNumber()&&Double.isFinite(duration.asDouble())&&duration.asDouble()>=0&&duration.asDouble()<=3600000)safe.put("durationMs",duration.asDouble());for(String key:List.of("valid","is_graded")){var v=raw.get(key);if(v!=null&&v.isBoolean())safe.put(camel(key),v.asBoolean());}for(String key:List.of("code","error_code")){var v=raw.get(key);if(v!=null&&v.isString()&&SAFE_CODES.contains(v.asText()))safe.put(key.equals("code")?"code":"errorCode",v.asText());}if(raw.has("failure_category"))safe.remove("attempt");safe.putAll(LocalDemoFailure.safe(raw));/* AI artifact IDs are private temporary IDs, not browser media identifiers. */return safe;}
    public void recordHttpFailure(UUID run,UUID submission,JsonNode details) {
        Map<String,Object> data=LocalDemoFailure.safe(details);
        if(!data.containsKey("failureCategory"))return;
        // This is an observed HTTP failure, not a synthesized model/stage completion.
        Map<String,Object> metadata=new LinkedHashMap<>();
        metadata.put("type","failed");metadata.put("phase",data.getOrDefault("phase","failed"));
        metadata.put("observedAt",Instant.now().toString());metadata.put("data",data);
        store.db().update("INSERT INTO submission_events(submission_id,event_type,metadata) SELECT ?,'local_ai_http_failure',?::jsonb WHERE EXISTS(SELECT 1 FROM grading_runs WHERE id=? AND submission_id=?)",submission,store.json().write(metadata),run,submission);
    }
    public Map<String,Object> failure(UUID submission) {
        var rows=store.db().queryForList("SELECT metadata::text FROM submission_events WHERE submission_id=? AND (event_type='local_ai_http_failure' OR (event_type='local_ai_event' AND metadata->>'type' IN('failed','run_failed'))) ORDER BY CASE WHEN event_type='local_ai_event' THEN 0 ELSE 1 END,id DESC LIMIT 20",submission);
        for(var row:rows){var failure=LocalDemoFailure.failure(store.json().read(row.get("metadata").toString()).path("data"));if(failure!=null)return failure;}
        return null;
    }
    private static String camel(String key){StringBuilder b=new StringBuilder();boolean upper=false;for(char c:key.toCharArray()){if(c=='_'){upper=true;continue;}b.append(upper?Character.toUpperCase(c):c);upper=false;}return b.toString();}
    public long lastSeq(UUID submission){UUID run=sync(submission);return store.db().queryForObject("SELECT coalesce(max(seq),0) FROM local_demo_public_events WHERE run_id=?",Long.class,run);}
    private UUID sync(UUID submission){UUID run=store.db().queryForObject("SELECT id FROM local_demo_runs WHERE submission_id=?",UUID.class,submission);tx.executeWithoutResult(t->{store.db().queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?::text,995012))",run.toString());var rows=store.db().queryForList("SELECT e.id,e.event_type,e.metadata,e.created_at FROM submission_events e LEFT JOIN local_demo_public_events p ON p.source_event_id=e.id WHERE e.submission_id=? AND p.seq IS NULL ORDER BY e.id LIMIT 200",submission);for(var row:rows){Map<String,Object> event=project(row);store.db().update("INSERT INTO local_demo_public_events(run_id,source_event_id,type,phase,state,created_at,data) VALUES(?,?,?,?,?,?::timestamptz,?::jsonb)",run,row.get("id"),event.get("type"),event.get("phase"),event.get("state"),event.get("createdAt"),store.json().write(event.get("data")));}});return run;}
    private Map<String,Object> project(Map<String,Object> row){String type=row.get("event_type").toString(),phase=backendPhase(type),state=backendState(phase);Map<String,Object> data=Map.of();var metadata=store.json().read(row.get("metadata").toString());String created=((java.sql.Timestamp)row.get("created_at")).toInstant().toString();if(type.equals("local_ai_event")||type.equals("local_ai_http_failure")){phase=metadata.path("phase").asText();type=metadata.path("type").asText();state="running";if(type.equals("failed"))state="failed";else if(type.equals("cancelled"))state="cancelled";data=JSON.convertValue(metadata.path("data"),Map.class);created=metadata.path("observedAt").asText();}else{if(metadata.path("code").asText().equals("unknown_after_dispatch")){phase="unknown";state="unknown";}Map<String,Object> safe=new LinkedHashMap<>();var code=metadata.get("code");if(code!=null&&code.isString()&&code.asText().matches("[a-z][a-z0-9_]{0,79}"))safe.put("errorCode",code.asText());data=safe;}return Map.of("type",safeType(type),"phase",phase,"state",state,"createdAt",created,"data",data);}
    public Object page(UUID submission,long after,int limit){if(after<0||limit<1||limit>100)throw ApiException.invalid("Некорректный курсор событий");UUID run=sync(submission);var rows=store.db().queryForList("SELECT seq,type,phase,state,created_at,data FROM local_demo_public_events WHERE run_id=? AND seq>? ORDER BY seq LIMIT ?",run,after,limit+1);List<Object> items=new ArrayList<>();long last=after;for(var row:rows.stream().limit(limit).toList()){last=((Number)row.get("seq")).longValue();items.add(Map.of("seq",last,"type",row.get("type"),"phase",row.get("phase"),"state",row.get("state"),"createdAt",((java.sql.Timestamp)row.get("created_at")).toInstant().toString(),"data",store.json().read(row.get("data").toString())));}return Map.of("items",items,"nextAfter",last,"hasMore",rows.size()>limit,"observer",observerStatus(submission));}
    private static String safeType(String t){return t.matches("[a-z][a-z0-9_]{0,79}")?t:"observation";}
    public static String backendPhase(String type){return switch(type){case "intent_created","target_validated"->"input_received";case "upload_staged","upload_ready","upload_rejected","image_deleted","document_processing","document_ready","document_failed"->"media_processing";case "queued","pre_dispatch_requeued"->"queued";case "dispatch_committed"->"ai_running";case "graded","ai_rejected"->"ai_completed";case "expert_queued"->"expert_queued";case "expert_draft","expert_sent","failed","cancelled"->type;case "expired","unknown_after_dispatch"->"unknown";default->type;};}
    private static String backendState(String phase){return switch(phase){case "queued"->"queued";case "ai_running"->"running";case "ai_completed"->"completed";case "expert_queued"->"awaiting_expert";case "expert_draft"->"reviewing";case "expert_sent"->"returned";case "failed","cancelled","unknown"->phase;default->"preparing";};}
    private static void fields(JsonNode n,String...keys){require(n.isObject()&&n.size()==keys.length);for(String k:keys)require(n.has(k));}
    private static void require(boolean ok){if(!ok)throw new IllegalArgumentException("Invalid observation page");}
}
